import sys

def max_sum(k, H):
    if k == 0:
        return 0
    if H >= k:
        return k * (k + 1) // 2
    x = k - H + 2
    m = (x + 1) // 2
    m = max(1, min(k + 1, m))
    sumL = 0
    if m > 1:
        cnt = m - 1
        sumL = cnt * H + (cnt - 1) * cnt // 2
    p = k - m + 1
    sumR = p * (p + 1) // 2
    return sumL + sumR

def main():
    n, H = map(int, sys.stdin.readline().split())
    lo, hi = 1, n
    ans = n
    while lo <= hi:
        mid = (lo + hi) // 2
        if max_sum(mid, H) >= n:
            ans = mid
            hi = mid - 1
        else:
            lo = mid + 1
    print(ans)

