MOD = 10**9 + 7

def get_divisors(n):
    divs = []
    i = 1
    while i * i <= n:
        if n % i == 0:
            divs.append(i)
            if i * i != n:
                divs.append(n // i)
        i += 1
    return divs

def mobius(n):
    if n == 1:
        return 1
    mu = 1
    i = 2
    while i * i <= n:
        if n % i == 0:
            n //= i
            if n % i == 0:
                return 0
            mu = -mu
        i += 1
    if n > 1:
        mu = -mu
    return mu

def modpow(base, exp, mod):
    res = 1
    base %= mod
    while exp > 0:
        if exp & 1:
            res = res * base % mod
        base = base * base % mod
        exp >>= 1
    return res

def main():
    x, y = map(int, sys.stdin.readline().split())
    if y % x != 0:
        print(0)
        return
    s = y // x
    divs = get_divisors(s)
    ans = 0
    for d in divs:
        mu = mobius(d)
        if mu == 0:
            continue
        k = s // d - 1
        ans = (ans + mu * modpow(2, k, MOD)) % MOD
    print(ans)

