MOD = 10**9 + 7

def get_primes(n):
    primes = []
    i = 2
    while i * i <= n:
        if n % i == 0:
            primes.append(i)
            while n % i == 0:
                n //= i
        i += 1
    if n > 1:
        primes.append(n)
    return primes

def get_divisors(n):
    divs = []
    i = 1
    while i * i <= n:
        if n % i == 0:
            divs.append(i)
            if i * i != n:
                divs.append(n // i)
        i += 1
    return divs

def mobius(d, primes):
    res = 1
    for p in primes:
        if d % p == 0:
            d //= p
            if d % p == 0:
                return 0
            res = -res
    return res

def main():
    x, y = map(int, sys.stdin.readline().split())
    if y % x != 0:
        print(0)
        return
    s = y // x
    primes = get_primes(s)
    divs = get_divisors(s)
    ans = 0
    for d in divs:
        mu = mobius(d, primes)
        if mu == 0:
            continue
        exp = s // d - 1
        ans = (ans + mu * pow(2, exp, MOD)) % MOD
    print(ans)

