    count = 0
    # K that do not divide n: all divisors of n-1 except 1
    for d in get_divisors(n - 1):
        if d >= 2:
            count += 1
    # K that divide n: check the condition
    for d in get_divisors(n):
        if d >= 2:
            m = n
            while m % d == 0:
                m //= d
            if m % d == 1:
