import sys
from math import factorial

MOD = 998244353

def main():
    data = sys.stdin.read().split()
    N = int(data[0])
    K = int(data[1])
    A = []
    idx = 2
    for i in range(N):
        row = list(map(int, data[idx:idx+N]))
        A.append(row)
        idx += N

    # Column graph
    col_adj = [[] for _ in range(N)]
    for x in range(N):
        for y in range(x+1, N):
            if all(A[i][x] + A[i][y] <= K for i in range(N)):
                col_adj[x].append(y)
                col_adj[y].append(x)

    # Row graph
    row_adj = [[] for _ in range(N)]
    for x in range(N):
        for y in range(x+1, N):
            if all(A[x][j] + A[y][j] <= K for j in range(N)):
                row_adj[x].append(y)
                row_adj[y].append(x)

    def components(adj):
        vis = [False] * N
        sizes = []
        for i in range(N):
            if not vis[i]:
                stack = [i]
                vis[i] = True
                sz = 0
                while stack:
                    u = stack.pop()
                    sz += 1
                    for v in adj[u]:
                        if not vis[v]:
                            vis[v] = True
                            stack.append(v)
                sizes.append(sz)
        return sizes

    row_sizes = components(row_adj)
    col_sizes = components(col_adj)

    ans = 1
    for s in row_sizes:
        ans = ans * factorial(s) % MOD
    for s in col_sizes:
        ans = ans * factorial(s) % MOD
    print(ans)

if __name__ == "__main__":
    main()

