MOD = 998244353

def main():
    data = sys.stdin.read().split()
    it = iter(data)
    N = int(next(it))
    K = int(next(it))
    a = [[int(next(it)) for _ in range(N)] for _ in range(N)]

    def components(is_row):
        adj = [[] for _ in range(N)]
        for i in range(N):
            for j in range(i+1, N):
                ok = True
                for k in range(N):
                    if is_row:
                        s = a[i][k] + a[j][k]
                    else:
                        s = a[k][i] + a[k][j]
                    if s > K:
                        ok = False
                        break
                if ok:
                    adj[i].append(j)
                    adj[j].append(i)
        vis = [False] * N
        facts = 1
        for i in range(N):
            if not vis[i]:
                sz = 0
                stack = [i]
                vis[i] = True
                while stack:
                    u = stack.pop()
                    sz += 1
                    for v in adj[u]:
                        if not vis[v]:
                            vis[v] = True
                            stack.append(v)
                f = 1
                for x in range(1, sz+1):
                    f = f * x % MOD
                facts = facts * f % MOD
        return facts

    ans = components(True) * components(False) % MOD
    print(ans)

