B = pb * inv_ab % MOD
invB = modinv(B)
AB = A * invB % MOD  # A/B

E = [[0] * k for _ in range(k)]

for x in range(k-1, -1, -1):
    for c in range(k-1, -1, -1):
        if x == 0:
            E[x][c] = E[1][c] if k > 1 else (c + 1 + AB) % MOD
