import sys

def main():
    n, m, k = map(int, sys.stdin.readline().split())
    days = []
    for _ in range(n):
        s = sys.stdin.readline().strip()
        pos = [i for i in range(m) if s[i] == '1']
        days.append(pos)

    INF = 10**9
    dp = [INF] * (k + 1)
    dp[0] = 0

    for pos in days:
        t = len(pos)
        costs = [INF] * (t + 1)
        costs[t] = 0
        for r in range(1, t + 1):
            min_span = INF
            for i in range(t - r + 1):
                span = pos[i + r - 1] - pos[i] + 1
                if span < min_span:
                    min_span = span
            s = t - r
            costs[s] = min_span

        new_dp = [INF] * (k + 1)
        for used in range(k + 1):
            if dp[used] == INF:
                continue
            for s in range(t + 1):
                if used + s > k:
                    break
                new_dp[used + s] = min(new_dp[used + s], dp[used] + costs[s])
        dp = new_dp

    print(min(dp))

