import sys

def main():
    a, b, w, x, c = map(int, sys.stdin.readline().split())
    if c <= a:
        print(0)
        return
    d = c - a
    pos = {}
    seq = []
    cur = b
    while cur not in pos:
        pos[cur] = len(seq)
        if cur >= x:
            seq.append(0)
            cur -= x
        else:
            seq.append(1)
            cur = w - x + cur
    prefix_len = pos[cur]
    cycle_len = len(seq) - prefix_len
    prefix_k = sum(seq[:prefix_len])
    cycle_k = sum(seq[prefix_len:])

    def k_of(t):
        if t <= prefix_len:
            return sum(seq[:t])
        rem = t - prefix_len
        full = rem // cycle_len
        r = rem % cycle_len
        return prefix_k + full * cycle_k + sum(seq[prefix_len:prefix_len + r])

    lo, hi = 0, 10**18
    ans = hi
    while lo <= hi:
        mid = (lo + hi) // 2
        if mid - k_of(mid) >= d:
            ans = mid
            hi = mid - 1
        else:
            lo = mid + 1
    print(ans)

