input = sys.stdin.readline

n, m = map(int, input().split())
intervals = []
for _ in range(n):
    k = int(input())
    for _ in range(k):
        l, r = map(int, input().split())
        intervals.append((l, r))

cov = [[[0] * (m + 2) for _ in range(m + 2)] for _ in range(m + 2)]
for k in range(1, m + 1):
    cnt = [[0] * (m + 2) for _ in range(m + 2)]
    for L, R in intervals:
        if L <= k <= R:
            cnt[L][R] += 1
    ps = [[0] * (m + 2) for _ in range(m + 2)]
    for i in range(1, m + 1):
        for j in range(1, m + 1):
            ps[i][j] = ps[i - 1][j] + ps[i][j - 1] - ps[i - 1][j - 1] + cnt[i][j]
    for l in range(1, k + 1):
        for r in range(k, m + 1):
            # sum L=l..k, R=k..r
            val = ps[k][r] - ps[l - 1][r] - ps[k][k - 1] + ps[l - 1][k - 1]
            cov[l][r][k] = val

dp = [[0] * (m + 2) for _ in range(m + 2)]
for length in range(1, m + 1):
    for l in range(1, m - length + 2):
        r = l + length - 1
        best = 0
        for k in range(l, r + 1):
            left = dp[l][k - 1] if k > l else 0
            right = dp[k + 1][r] if k < r else 0
            best = max(best, cov[l][r][k] ** 2 + left + right)
        dp[l][r] = best

print(dp[1][m])

