import sys
MOD = 10**9 + 7

def main():
    data = sys.stdin.read().split()
    n = int(data[0])
    k = int(data[1])
    s = data[2]
    fact = [1] * (n + 1)
    for i in range(1, n + 1):
        fact[i] = fact[i - 1] * i % MOD
    invfact = [1] * (n + 1)
    invfact[n] = pow(fact[n], MOD - 2, MOD)
    for i in range(n, 0, -1):
        invfact[i - 1] = invfact[i] * i % MOD
    def C(a, b):
        if b < 0 or b > a or a < 0:
            return 0
        return fact[a] * invfact[b] % MOD * invfact[a - b] % MOD
    pow10 = [1] * n
    for i in range(1, n):
        pow10[i] = pow10[i - 1] * 10 % MOD
    ans = 0
    # end-reaching contributions
    for i in range(n):
        ans = (ans + int(s[i]) * pow10[n - 1 - i] % MOD * C(i, k)) % MOD
    if k == 0:
        print(ans)
        return
    # non-end: suf[q] = sum_{j=q}^{n-2} C(j, k-1) * 10^{n-2-j}
    suf = [0] * (n)
    for q in range(n - 2, -1, -1):
        suf[q] = (C(q, k - 1) * pow10[n - 2 - q] + (suf[q + 1] if q + 1 < n else 0)) % MOD
    for i in range(n - 1):
        ans = (ans + int(s[i]) * suf[i]) % MOD
    print(ans)

if __name__ == "__main__":
    main()

