from math import inf

def main():
    input = sys.stdin.read
    data = input().split()
    n = int(data[0])
    a = list(map(int, data[1:]))
    MAXP = 41
    cnt = [0] * MAXP
    extras_minp = [0] * MAXP
    for x in a:
        if x & (x - 1) == 0:
            p = x.bit_length() - 1
            if p < MAXP:
                cnt[p] += 1
        else:
            p = (x - 1).bit_length()
            if p < MAXP:
                extras_minp[p] += 1
    req = [0] * (MAXP + 1)
    for i in range(MAXP - 1, -1, -1):
        req[i] = req[i + 1] + extras_minp[i]
    N = n + 1
    min_sum = [inf] * N
    max_sum = [-inf] * N
    min_sum[0] = 0
    max_sum[0] = 0
    LOG = 17
    for i in range(MAXP - 1, -1, -1):
        stmin = [[inf] * N for _ in range(LOG)]
        stmax = [[-inf] * N for _ in range(LOG)]
        for j in range(N):
            stmin[0][j] = min_sum[j]
            stmax[0][j] = max_sum[j]
        for k in range(1, LOG):
            for j in range(N - (1 << k) + 1):
                stmin[k][j] = min(stmin[k - 1][j], stmin[k - 1][j + (1 << (k - 1))])
                stmax[k][j] = max(stmax[k - 1][j], stmax[k - 1][j + (1 << (k - 1))])
        def rmin(l, r):
            if l > r:
                return inf
            k = (r - l + 1).bit_length() - 1
            return min(stmin[k][l], stmin[k][r - (1 << k) + 1])
        def rmax(l, r):
            if l > r:
                return -inf
            k = (r - l + 1).bit_length() - 1
            return max(stmax[k][l], stmax[k][r - (1 << k) + 1])
        newmin = [inf] * N
        newmax = [-inf] * N
        c = cnt[i]
        rn = req[i + 1]
        for s in range(N):
            lo = max(0, c - s, rn)
            hi = min(s, c)
            if lo <= hi:
                mn = rmin(lo, hi)
                mx = rmax(lo, hi)
                if mn < inf:
                    newmin[s] = s + mn
                    newmax[s] = s + mx
        min_sum = newmin
        max_sum = newmax
    res = []
    for m in range(1, n + 1):
        if min_sum[m] <= n <= max_sum[m]:
            res.append(m)
    if not res:
        print(-1)
    else:
        print(' '.join(map(str, res)))

