    n = int(data[0])
    L = []
    R = []
    idx = 1
    for i in range(n):
        L.append(int(data[idx]))
        R.append(int(data[idx + 1]))
        idx += 2
    maxr = max(R)
    tot = [R[i] - L[i] + 1 for i in range(n)]
    def p_lt(i, k):
        if R[i] < k:
            return 1.0
        if L[i] >= k:
            return 0.0
        return (min(R[i], k - 1) - L[i] + 1) / tot[i]
    def p_ge(i, k):
        return 1.0 - p_lt(i, k)
    ans = 0.0
    for k in range(1, maxr + 2):
        pall = 1.0
        for i in range(n):
            pall *= p_lt(i, k)
        pex = 0.0
        for i in range(n):
            prod = p_ge(i, k)
            for j in range(n):
                if j != i:
                    prod *= p_lt(j, k)
            pex += prod
        p_sec_lt = pall + pex
        p_sec_ge = 1.0 - p_sec_lt
        ans += p_sec_ge
    print("%.10f" % ans)

