import sys
import random
import math

def dist2(a, b):
    return (a[0] - b[0]) ** 2 + (a[1] - b[1]) ** 2

def dist(a, b):
    return math.sqrt(dist2(a, b))

def circumcircle(a, b, c):
    ax, ay = a
    bx, by = b
    cx, cy = c
    d = 2 * (ax * (by - cy) + bx * (cy - ay) + cx * (ay - by))
    if abs(d) < 1e-12:
        return None
    ux = ((ax * ax + ay * ay) * (by - cy) + (bx * bx + by * by) * (cy - ay) + (cx * cx + cy * cy) * (ay - by)) / d
    uy = ((ax * ax + ay * ay) * (cx - bx) + (bx * bx + by * by) * (ax - cx) + (cx * cx + cy * cy) * (bx - ax)) / d
    r = dist((ux, uy), a)
    return (ux, uy, r)

def circle_from_two(a, b):
    cx = (a[0] + b[0]) / 2.0
    cy = (a[1] + b[1]) / 2.0
    r = dist(a, b) / 2.0
    return (cx, cy, r)

def is_in_circle(p, cir, eps=1e-9):
    if cir is None:
        return False
    return dist(p, (cir[0], cir[1])) <= cir[2] + eps

def min_enclosing_circle(points):
    pts = points[:]
    random.shuffle(pts)
    n = len(pts)
    if n == 0:
        return None
    if n == 1:
        return (pts[0][0], pts[0][1], 0.0)
    cir = circle_from_two(pts[0], pts[1])
    for i in range(2, n):
        if not is_in_circle(pts[i], cir):
            cir = min_circle_with_point(pts[:i], pts[i])
    return cir

def min_circle_with_point(points, q):
    pts = points[:]
    random.shuffle(pts)
    cir = circle_from_two(pts[0], q) if pts else (q[0], q[1], 0.0)
    for i in range(len(pts)):
        if not is_in_circle(pts[i], cir):
            cir = min_circle_with_two_points(pts[:i], pts[i], q)
    return cir

def min_circle_with_two_points(points, q1, q2):
    cir = circle_from_two(q1, q2)
    for p in points:
        if not is_in_circle(p, cir):
            cc = circumcircle(p, q1, q2)
            if cc:
                cir = cc
    return cir

def cross(o, a, b):
    return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

def convex_hull(points):
    pts = sorted(set(points))
    if len(pts) <= 1:
        return pts
    lower = []
    for p in pts:
        while len(lower) >= 2 and cross(lower[-2], lower[-1], p) <= 0:
            lower.pop()
        lower.append(p)
    upper = []
    for p in reversed(pts):
        while len(upper) >= 2 and cross(upper[-2], upper[-1], p) <= 0:
            upper.pop()
        upper.append(p)
    return lower[:-1] + upper[:-1]

def point_in_convex(hull, p):
    n = len(hull)
    if n == 0:
        return False
    if n == 1:
        return hull[0] == p
    if n == 2:
        return abs(cross(hull[0], hull[1], p)) < 1e-9 and min(hull[0][0], hull[1][0]) - 1e-9 <= p[0] <= max(hull[0][0], hull[1][0]) + 1e-9 and min(hull[0][1], hull[1][1]) - 1e-9 <= p[1] <= max(hull[0][1], hull[1][1]) + 1e-9
    for i in range(n):
        if cross(hull[i], hull[(i + 1) % n], p) < -1e-9:
            return False
    return True

def segments_intersect(a, b, c, d):
    def ori(p, q, r):
        val = cross(p, q, r)
        if abs(val) < 1e-9:
            return 0
        return 1 if val > 0 else 2
    o1 = ori(a, b, c)
    o2 = ori(a, b, d)
    o3 = ori(c, d, a)
    o4 = ori(c, d, b)
    if o1 != o2 and o3 != o4:
        return True
    return False

def convex_intersect(h1, h2):
    n1, n2 = len(h1), len(h2)
    if n1 == 0 or n2 == 0:
        return False
    for i in range(n1):
        for j in range(n2):
            if segments_intersect(h1[i], h1[(i + 1) % n1], h2[j], h2[(j + 1) % n2]):
                return True
    if point_in_convex(h1, h2[0]) or point_in_convex(h2, h1[0]):
        return True
    return False

def check(inner, outer):
    if not inner:
        return True
    cir = min_enclosing_circle(inner)
    if cir is None:
        return True
    cx, cy, r = cir
    for p in outer:
        if dist(p, (cx, cy)) <= r + 1e-8:
            return False
    return True

def can_separate(A, B):
    hA = convex_hull(A)
    hB = convex_hull(B)
    if not convex_intersect(hA, hB):
        return True
    A_in_B = all(point_in_convex(hB, p) for p in A)
    B_in_A = all(point_in_convex(hA, p) for p in B)
    if A_in_B and not B_in_A:
        return check(A, B)
    if B_in_A and not A_in_B:
        return check(B, A)
    return False

def main():
    data = sys.stdin.read().split()
    it = iter(data)
    n = int(next(it))
    m = int(next(it))
    A = [(int(next(it)), int(next(it))) for _ in range(n)]
    B = [(int(next(it)), int(next(it))) for _ in range(m)]
    if can_separate(A, B):
        print("YES")
    else:
        print("NO")

