def circle_from_2(p, q):
    c = ((p[0] + q[0]) / 2.0, (p[1] + q[1]) / 2.0)
    r2 = dist2(p, c)
    return c, r2

def circle_from_3(a, b, c):
    ax, ay = a
    bx, by = b
    cx, cy = c
    d = 2 * (ax * (by - cy) + bx * (cy - ay) + cx * (ay - by))
    if abs(d) < 1e-12:
        # collinear, take farthest pair
        pts = [a, b, c]
        maxd = -1
        best = None
        for i in range(3):
            for j in range(i + 1, 3):
                dd = dist2(pts[i], pts[j])
                if dd > maxd:
                    maxd = dd
                    best = (pts[i], pts[j])
        return circle_from_2(*best)
    ux = ((ax * ax + ay * ay) * (by - cy) + (bx * bx + by * by) * (cy - ay) + (cx * cx + cy * cy) * (ay - by)) / d
    uy = ((ax * ax + ay * ay) * (cx - bx) + (bx * bx + by * by) * (ax - cx) + (cx * cx + cy * cy) * (bx - ax)) / d
    c = (ux, uy)
    r2 = dist2(a, c)
    return c, r2

def welzl(pts):
    pts = pts[:]
    random.shuffle(pts)
    n = len(pts)
    if n == 0:
        return (0, 0), 0
    c, r2 = pts[0], 0.0
    for i in range(1, n):
        if dist2(pts[i], c) > r2 + 1e-9:
            c, r2 = pts[i], 0.0
            for j in range(i):
                if dist2(pts[j], c) > r2 + 1e-9:
                    c, r2 = circle_from_2(pts[i], pts[j])
                    for k in range(j):
                        if dist2(pts[k], c) > r2 + 1e-9:
                            c, r2 = circle_from_3(pts[i], pts[j], pts[k])
    return c, r2

def cross(o, a, b):
    return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

def convex_hull(pts):
    pts = sorted(set(pts))
    if len(pts) <= 1:
        return pts
    lower = []
    for p in pts:
        while len(lower) >= 2 and cross(lower[-2], lower[-1], p) <= 0:
            lower.pop()
        lower.append(p)
    upper = []
    for p in reversed(pts):
        while len(upper) >= 2 and cross(upper[-2], upper[-1], p) <= 0:
            upper.pop()
        upper.append(p)
    return lower[:-1] + upper[:-1]

def max_dot(hull, vx, vy):
    h = len(hull)
    if h == 0:
        return -1e30
    if h == 1:
        return hull[0][0] * vx + hull[0][1] * vy
    # ternary search on circular unimodal
    def dot(i):
        p = hull[i % h]
        return p[0] * vx + p[1] * vy
    lo, hi = 0, h
    while hi - lo > 5:
        m1 = lo + (hi - lo) // 3
        m2 = hi - (hi - lo) // 3
        if dot(m1) < dot(m2):
            lo = m1
        else:
            hi = m2
    mx = dot(lo)
    for i in range(lo, hi + 1):
        mx = max(mx, dot(i))
    return mx

def min_dot(hull, vx, vy):
    return -max_dot(hull, -vx, -vy)

def hulls_strictly_disjoint(ha, hb):
    if not ha or not hb:
        return True
    dirs = []
    for hull in (ha, hb):
        h = len(hull)
        for i in range(h):
            x1, y1 = hull[i]
            x2, y2 = hull[(i + 1) % h]
            dx, dy = x2 - x1, y2 - y1
            dirs.append((-dy, dx))  # outward-ish normal
    for vx, vy in dirs:
        if vx == 0 and vy == 0:
            continue
        maxa = max_dot(ha, vx, vy)
        mina = min_dot(ha, vx, vy)
        maxb = max_dot(hb, vx, vy)
        minb = min_dot(hb, vx, vy)
        if maxa < minb - 1e-9 or maxb < mina - 1e-9:
            return True
    return False

def all_outside(c, r2, pts):
    for p in pts:
        if dist2(p, c) <= r2 + 1e-8:
            return False
    return True

