    data = sys.stdin.read().split()
    it = iter(data)
    n = int(next(it))
    m = int(next(it))
    A = [(int(next(it)), int(next(it))) for _ in range(n)]
    B = [(int(next(it)), int(next(it))) for _ in range(m)]
    ha = convex_hull(A)
    hb = convex_hull(B)
    if hulls_strictly_disjoint(ha, hb):
        print("YES")
        return
    c, r2 = welzl(A)
    if all_outside(c, r2, B):
        print("YES")
        return
    c, r2 = welzl(B)
    if all_outside(c, r2, A):
        print("YES")
        return
    print("NO")

