class FenwickMax:
    def __init__(self, n):
        self.n = n
        self.t = [-10**9] * (n + 1)
    def update(self, i, v):
        while i <= self.n:
            if v > self.t[i]:
                self.t[i] = v
            i += i & -i
    def query(self, i):
        res = -10**9
        while i > 0:
            if self.t[i] > res:
                res = self.t[i]
            i -= i & -i
        return res

class FenwickMin:
    def __init__(self, n):
        self.n = n
        self.t = [10**9] * (n + 1)
    def update(self, i, v):
        while i <= self.n:
            if v < self.t[i]:
                self.t[i] = v
            i += i & -i
    def query(self, i):
        res = 10**9
        while i > 0:
            if self.t[i] < res:
                res = self.t[i]
            i -= i & -i
        return res

