    L = nxtb - prevb - 1
    L1 = x - prevb - 1
    L2 = nxtb - x - 1
    cap -= gap_ships(L)
    cap += gap_ships(L1) + gap_ships(L2)
    add_blocked(x)
    is_blocked[x] = True
    if cap < k:
        ans = i
        break

