MOD = 10**9 + 7

def mat_mult(A, B, m):
    C = [[0] * m for _ in range(m)]
    for i in range(m):
        for k in range(m):
            if A[i][k]:
                aik = A[i][k]
                for j in range(m):
                    C[i][j] = (C[i][j] + aik * B[k][j]) % MOD
    return C

def mat_pow(M, p, m):
    res = [[0] * m for _ in range(m)]
    for i in range(m):
        res[i][i] = 1
    while p:
        if p & 1:
            res = mat_mult(res, M, m)
        M = mat_mult(M, M, m)
        p >>= 1
    return res

