    return pts

def sub(a, b):
    return (a[0] - b[0], a[1] - b[1], a[2] - b[2])

def cross(a, b):
    return (a[1]*b[2] - a[2]*b[1], a[2]*b[0] - a[0]*b[2], a[0]*b[1] - a[1]*b[0])

def dot(a, b):
    return a[0]*b[0] + a[1]*b[1] + a[2]*b[2]

def get_plane(pts):
    nrm = (0, 0, 0)
    for i in range(len(pts)):
        a = pts[i]
        b = pts[(i + 1) % len(pts)]
        nrm = (nrm[0] + (a[1] - b[1]) * (a[2] + b[2]),
               nrm[1] + (a[2] - b[2]) * (a[0] + b[0]),
               nrm[2] + (a[0] - b[0]) * (a[1] + b[1]))
    # fallback first 3 points if degenerate
    if nrm == (0, 0, 0):
        nrm = cross(sub(pts[1], pts[0]), sub(pts[2], pts[0]))
    d = dot(nrm, pts[0])
    return nrm, d

def project(p, nrm):
    ax = abs(nrm[0])
    ay = abs(nrm[1])
    az = abs(nrm[2])
    if az >= ax and az >= ay:
        return (p[0], p[1])
    if ay >= ax:
        return (p[0], p[2])
    return (p[1], p[2])

def point_in_poly(pt, poly2d):
    x, y = pt
    n = len(poly2d)
    inside = False
    j = n - 1
    for i in range(n):
        xi, yi = poly2d[i]
        xj, yj = poly2d[j]
        if ((yi > y) != (yj > y)) and (x < (xj - xi) * (y - yi) / (yj - yi + 0.0) + xi):
            inside = not inside
        j = i
    return inside

def count_signed_cross(polyP, polyQ):
    nrm, d = get_plane(polyP)
    if nrm == (0, 0, 0):
        return 0, 0
    poly2d = [project(p, nrm) for p in polyP]
    plus = minus = 0
    m = len(polyQ)
    for i in range(m):
        a = polyQ[i]
        b = polyQ[(i + 1) % m]
        da = dot(nrm, a) - d
        db = dot(nrm, b) - d
        if da * db >= 0:
            continue
        t = da / (da - db + 0.0)
        inter = (a[0] + t * (b[0] - a[0]), a[1] + t * (b[1] - a[1]), a[2] + t * (b[2] - a[2]))
        inter2 = project(inter, nrm)
        if point_in_poly(inter2, poly2d):
            if da > 0:
                plus += 1
            else:
                minus += 1
    return plus, minus

