import sys

def sub(a, b):
    return (a[0] - b[0], a[1] - b[1], a[2] - b[2])

def cross(a, b):
    return (a[1] * b[2] - a[2] * b[1], a[2] * b[0] - a[0] * b[2], a[0] * b[1] - a[1] * b[0])

def dot(a, b):
    return a[0] * b[0] + a[1] * b[1] + a[2] * b[2]

def crosses(P, Q):
    n = len(P)
    p0, p1, p2 = P[0], P[1], P[2]
    v1 = sub(p1, p0)
    v2 = sub(p2, p0)
    N = cross(v1, v2)
    if N == (0, 0, 0):
        return False
    D = dot(N, p0)
    ax = 0
    if abs(N[1]) > abs(N[ax]):
        ax = 1
    if abs(N[2]) > abs(N[ax]):
        ax = 2
    def proj(p):
        return tuple(p[i] for i in range(3) if i != ax)
    poly = [proj(p) for p in P]
    def inside(pt):
        x, y = pt
        cnt = 0
        for i in range(n):
            a = poly[i]
            b = poly[(i + 1) % n]
            if (a[1] > y) != (b[1] > y):
                atx = a[0] + (b[0] - a[0]) * (y - a[1]) / (b[1] - a[1])
                if x < atx:
                    cnt += 1
        return cnt % 2 == 1
    pos = neg = 0
    m = len(Q)
    for i in range(m):
        p = Q[i]
        q = Q[(i + 1) % m]
        da = dot(N, p) - D
        db = dot(N, q) - D
        if da * db < 0:
            t = da / (da - db)
            inter = (p[0] + t * (q[0] - p[0]), p[1] + t * (q[1] - p[1]), p[2] + t * (q[2] - p[2]))
            if inside(proj(inter)):
                if da > 0:
                    pos += 1
                else:
                    neg += 1
    return pos != neg

