import sys
MOD = 10**9 + 7

def mat_mul(A, B):
    n = len(A)
    C = [[0] * n for _ in range(n)]
    for i in range(n):
        for k in range(n):
            if A[i][k]:
                aik = A[i][k]
                for j in range(n):
                    C[i][j] = (C[i][j] + aik * B[k][j]) % MOD
    return C

def mat_pow(M, p):
    n = len(M)
    R = [[0] * n for _ in range(n)]
    for i in range(n):
        R[i][i] = 1
    while p:
        if p & 1:
            R = mat_mul(R, M)
        M = mat_mul(M, M)
        p >>= 1
    return R

def main():
    data = sys.stdin.read().split()
    n = int(data[0])
    x = int(data[1])
    ds = list(map(int, data[2:2+n]))
    cnt = [0] * 101
    for d in ds:
        cnt[d] += 1
    if x == 0:
        print(1)
        return
    a = [0] * 100
    a[0] = 1
    s = 1
    for k in range(1, 100):
        ak = 0
        for d in range(1, 101):
            if k >= d:
                ak = (ak + cnt[d] * a[k - d]) % MOD
        if k < 100:
            a[k] = ak
        s = (s + ak) % MOD
        if k == x:
            print(s)
            return
    # now at k=99, a[0..99] filled, s = sum up to 99
    # state: [a99, a98, ..., a0, s]
    state = [a[99 - i] for i in range(100)] + [s]
    # build trans 101 x 101
    sz = 101
    T = [[0] * sz for _ in range(sz)]
    # new_a coeffs: T[0][d-1] += cnt[d]
    for d in range(1, 101):
        T[0][d - 1] = (T[0][d - 1] + cnt[d]) % MOD
    # shift: new state[1..99] = old[0..98]
    for i in range(1, 100):
        T[i][i - 1] = 1
    # new_s = old_s + new_a  => T[100][100] =1, T[100][j] += T[0][j]
    T[100][100] = 1
    for j in range(100):
        T[100][j] = (T[100][j] + T[0][j]) % MOD
    # raise T^{x-99}
    P = mat_pow(T, x - 99)
    # apply to state
    news = 0
    for j in range(sz):
        news = (news + P[100][j] * state[j]) % MOD
    print(news)

