import sys

def get_sz(x, n):
    sz = n
    r = (n + 1) // 2
    while r != x:
        leftsz = (sz - 1) // 2
        offset = (leftsz + 1) // 2
        if x < r:
            sz = leftsz
            r -= offset
        else:
            sz = leftsz
            r += offset
    return sz

def get_left(x, n):
    sz = get_sz(x, n)
    if sz == 1:
        return None
    leftsz = (sz - 1) // 2
    offset = (leftsz + 1) // 2
    return x - offset

def get_right(x, n):
    sz = get_sz(x, n)
    if sz == 1:
        return None
    leftsz = (sz - 1) // 2
    offset = (leftsz + 1) // 2
    return x + offset

def get_parent(x, n):
    root = (n + 1) // 2
    if x == root:
        return None
    sz = n
    r = root
    p = None
    while r != x:
        p = r
        leftsz = (sz - 1) // 2
        offset = (leftsz + 1) // 2
        if x < r:
            sz = leftsz
            r -= offset
        else:
            sz = leftsz
            r += offset
    return p

def main():
    data = sys.stdin.read().split()
    it = iter(data)
    n = int(next(it))
    q = int(next(it))
    out = []
    for _ in range(q):
        u = int(next(it))
        s = next(it)
        curr = u
        for c in s:
            if c == 'L':
                nxt = get_left(curr, n)
                if nxt is not None:
                    curr = nxt
            elif c == 'R':
                nxt = get_right(curr, n)
                if nxt is not None:
                    curr = nxt
            elif c == 'U':
                nxt = get_parent(curr, n)
                if nxt is not None:
                    curr = nxt
        out.append(str(curr))
    sys.stdout.write('\n'.join(out) + '\n')

