        a, b = map(int, sys.stdin.readline().split())
        adj[a].append(b)
        adj[b].append(a)

    def get_size_towards(root, target):
        size = [0] * (n + 1)
        def dfs(u, p):
            size[u] = 1
            for v in adj[u]:
                if v != p:
                    dfs(v, u)
                    size[u] += size[v]
        dfs(root, 0)
        # find the child of root that contains target
        def find_child(u, p):
            if u == target:
                return True
            for v in adj[u]:
                if v != p:
                    if find_child(v, u):
                        return True
            return False
        towards = 0
        for v in adj[root]:
            if find_child(v, root):
                towards = size[v]
                break
        return n - towards

    A = get_size_towards(x, y)
    B = get_size_towards(y, x)
    print(n * (n - 1) - A * B)

