def main():
    data = sys.stdin.read().split()
    n = int(data[0])
    m = int(data[1])
    parent = list(range(n + 1))
    rank = [0] * (n + 1)

    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        px, py = find(x), find(y)
        if px == py:
            return False
        if rank[px] < rank[py]:
            parent[px] = py
        elif rank[px] > rank[py]:
            parent[py] = px
        else:
            parent[py] = px
            rank[px] += 1
        return True

    idx = 2
    valid = True
    for _ in range(m):
        a = int(data[idx])
        b = int(data[idx + 1])
        idx += 2
        if not union(a, b):
            valid = False
            break

    if valid:
        roots = set(find(i) for i in range(1, n + 1))
        if len(roots) != 1:
            valid = False

    print("yes" if valid else "no")

