class Fenwick:
    def __init__(self, n):
        self.n = n
        self.t = [0] * (n + 1)
    def update(self, i, v):
        while i <= self.n:
            if v > self.t[i]:
                self.t[i] = v
            i += i & -i
    def query(self, i):
        r = 0
        while i > 0:
            if self.t[i] > r:
                r = self.t[i]
            i -= i & -i
        return r

