import sys
from collections import deque

def get_result(s, n, k):
    if k == 1:
        return s
    dq = deque(s[:k])
    rev = True  # after initial reverse
    res = []
    idx = k
    for _ in range(n - k + 1):
        if rev:
            res.append(dq.pop())
            if idx < n:
                dq.appendleft(s[idx])
                idx += 1
        else:
            res.append(dq.popleft())
            if idx < n:
                dq.append(s[idx])
                idx += 1
        rev = not rev
    # remaining m = k-1 chars in current orientation
    if rev:
        res.extend(reversed(dq))
    else:
        res.extend(dq)
    return ''.join(res)

