import math

def factorize(b):
    factors = []
    # Check 2
    if b % 2 == 0:
        cnt = 0
        while b % 2 == 0:
            b //= 2
            cnt += 1
        factors.append((2, cnt))
    # Odd factors
    i = 3
    while i * i <= b:
        if b % i == 0:
            cnt = 0
            while b % i == 0:
                b //= i
                cnt += 1
            factors.append((i, cnt))
        i += 2
    if b > 1:
        factors.append((b, 1))
    return factors

def valuation(n, p):
    if p > n:
        return 0
    v = 0
    pp = p
    while pp <= n:
        v += n // pp
        if pp > n // p:
            break
        pp *= p
    return v

def main():
    n, b = map(int, sys.stdin.readline().split())
    factors = factorize(b)
    ans = float('inf')
    for p, a in factors:
        v = valuation(n, p)
        ans = min(ans, v // a)
    print(ans if ans != float('inf') else 0)

