import sys
from collections import defaultdict

class SegTree:
    def __init__(self, n, inf):
        self.n = n
        self.inf = inf
        self.t = [inf] * (4 * n)

    def update(self, v, tl, tr, pos, val):
        if tl == tr:
            self.t[v] = val
            return
        tm = (tl + tr) // 2
        if pos <= tm:
            self.update(2 * v, tl, tm, pos, val)
        else:
            self.update(2 * v + 1, tm + 1, tr, pos, val)
        self.t[v] = min(self.t[2 * v], self.t[2 * v + 1])

    def query(self, v, tl, tr, l, r):
        if l > r:
            return self.inf
        if l == tl and r == tr:
            return self.t[v]
        tm = (tl + tr) // 2
        return min(self.query(2 * v, tl, tm, l, min(r, tm)),
                   self.query(2 * v + 1, tm + 1, tr, max(l, tm + 1), r))

def main():
    input = sys.stdin.read().split()
    n = int(input[0])
    q = int(input[1])
    queries = []
    xs = set()
    idx = 2
    for _ in range(q):
        x = int(input[idx])
        y = int(input[idx + 1])
        d = input[idx + 2]
        queries.append((x, y, d))
        xs.add(x)
        idx += 3
    xs = sorted(xs)
    comp = {x: i for i, x in enumerate(xs)}
    m = len(xs)
    INF = n + 2
    stu = SegTree(m, INF)
    stl = SegTree(m, INF)
    used = set()
    out = []
    for x, y, d in queries:
        if x in used:
            out.append('0')
            continue
        used.add(x)
        ci = comp[x]
        if d == 'L':
            lo, hi = 0, ci - 1
            best = -1
            while lo <= hi:
                mid = (lo + hi) // 2
                if stu.query(1, 0, m - 1, mid, ci - 1) <= y:
                    best = mid
                    lo = mid + 1
                else:
                    hi = mid - 1
            if best == -1:
                stopx = 0
            else:
                stopx = xs[best]
            eaten = x - stopx
            stl.update(1, 0, m - 1, ci, stopx)
            out.append(str(eaten))
        else:
            lo, hi = ci + 1, m - 1
            best = m
            while lo <= hi:
                mid = (lo + hi) // 2
                if stl.query(1, 0, m - 1, ci + 1, mid) <= x:
                    best = mid
                    hi = mid - 1
                else:
                    lo = mid + 1
            if best == m:
                stopy = 0
            else:
                stopy = n + 1 - xs[best]
            eaten = y - stopy
            stu.update(1, 0, m - 1, ci, stopy)
            out.append(str(eaten))
    sys.stdout.write('\n'.join(out) + '\n')

