def solve():
    t = int(input())
    out = []
    for _ in range(t):
        n = int(input())
        s = input().strip()
        orig = [0 if c == 'L' else 1 for c in s]
        ans = INF
        for d0 in range(2):
            for d1 in range(2):
                cost01 = (d0 != orig[0]) + (d1 != orig[1])
                # costs[a][b] = min cost after assigning up to current, dir[-2]=a, dir[-1]=b
                costs = [[INF]*2 for _ in range(2)]
                costs[d0][d1] = cost01
                for i in range(2, n):
                    newc = [[INF]*2 for _ in range(2)]
                    for a in range(2):
