                            if costs[a][b] >= INF:
                                continue
                            for c in range(2):
                                if logical(a, b, c):
                                    add = (c != orig[i])
                                    nc = costs[a][b] + add
                                    if nc < newc[b][c]:
                                        newc[b][c] = nc
                    costs = newc
                # now check wrap: player n-1 and player 0
                for a in range(2):  # dir n-2
                    for b in range(2):  # dir n-1
                        if costs[a][b] >= INF:
                            continue
                        if logical(a, b, d0) and logical(b, d0, d1):
                            if costs[a][b] < ans:
