import sys
from collections import defaultdict

class Fenwick:
    def __init__(self, n):
        self.n = n
        self.bit = [0] * (n + 1)
    def add(self, i, delta):
        i += 1
        while i <= self.n:
            self.bit[i] += delta
            i += i & -i
    def sum(self, i):
        s = 0
        i += 1
        while i > 0:
            s += self.bit[i]
            i -= i & -i
        return s
    def prefix(self, r):
        if r < 0:
            return 0
        return self.sum(min(r, self.n - 1))

def main():
    input = sys.stdin.read().split()
    n = int(input[0])
