        a = int(input[idx])
        t = int(input[idx+1])
        x = int(input[idx+2])
        queries.append((a, t, x))
        idx += 3
    updates = defaultdict(list)
    for a, t, x in queries:
        if a != 3:
            updates[x].append(t)
    fens = {}
    pos = {}
    for x, times in updates.items():
        times.sort()
        pos[x] = {tm: i for i, tm in enumerate(times)}
        fens[x] = Fenwick(len(times))
    out = []
    for a, t, x in queries:
        if a == 1:
            i = pos[x][t]
            fens[x].add(i, 1)
        elif a == 2:
            i = pos[x][t]
            fens[x].add(i, -1)
        else:
            if x not in fens:
                out.append('0')
                continue
            times = updates[x]
            import bisect
            r = bisect.bisect_right(times, t) - 1
            out.append(str(fens[x].prefix(r)))
    print('\n'.join(out))

