def on_line(a, b, p):
    return (b[0] - a[0]) * (p[1] - a[1]) == (p[0] - a[0]) * (b[1] - a[1])

def remaining_collinear(pts, a, b):
    rem = [p for p in pts if not on_line(a, b, p)]
    if len(rem) <= 2:
        return True
    c, d = rem[0], rem[1]
    for p in rem[2:]:
        if not on_line(c, d, p):
            return False
    return True

