    n = int(data[0])
    m = int(data[1])
    grid = data[2:2+n]
    S = []
    minx = n
    maxx = -1
    miny = m
    maxy = -1
    for i in range(n):
        for j in range(m):
            if grid[i][j] == 'X':
                S.append((i, j))
                if i < minx:
                    minx = i
                if i > maxx:
                    maxx = i
                if j < miny:
                    miny = j
                if j > maxy:
                    maxy = j
    k = len(S)
    if k == 0:
        print("NO")
        return
    wS = maxx - minx + 1
    hS = maxy - miny + 1
    area = 2 * k
    possible = False
    # find all divisors
    divs = []
    i = 1
    while i * i <= area:
        if area % i == 0:
            divs.append(i)
            if i * i != area:
                divs.append(area // i)
        i += 1
    for wu in divs:
        hu = area // wu
        if wu < wS or hu < hS:
            continue
        dx_abs = wu - wS
        dy_abs = hu - hS
        for sdx in (dx_abs, -dx_abs) if dx_abs != 0 else (0,):
            for sdy in (dy_abs, -dy_abs) if dy_abs != 0 else (0,):
                if sdx == 0 and sdy == 0:
                    continue
                overlap = False
                for x, y in S:
                    nx = x - sdx
                    ny = y - sdy
                    if 0 <= nx < n and 0 <= ny < m and grid[nx][ny] == 'X':
                        overlap = True
                        break
                if not overlap:
                    possible = True
                    break
            if possible:
                break
        if possible:
            break
    print("YES" if possible else "NO")

