# likes
for idx in likes:
    wi = w[idx]
    dp = [[[0] * (m + 1) for _ in range(m + 1)] for _ in range(m + 1)]
    dp[0][0][0] = 1
    for x in range(m + 1):
        for y in range(m - x + 1):
            tot = P + Q + x - y
            if tot == 0:
                continue
            invt = INV[tot]
            plike = (P + x) * invt % MOD
            pdis = (Q - y) * invt % MOD if Q >= y else 0
            for z in range(x + 1):
                pr = dp[x][y][z]
                if pr == 0:
                    continue
                if x + y == m:
                    continue
                # pick like
                pthis = (wi + z) * INV[P + x] % MOD if P + x else 0
                dp[x + 1][y][z + 1] = (dp[x + 1][y][z + 1] + pr * plike % MOD * pthis) % MOD
                dp[x + 1][y][z] = (dp[x + 1][y][z] + pr * plike % MOD * (1 - pthis + MOD)) % MOD
                # pick dis
                if y < m and Q > y:
                    dp[x][y + 1][z] = (dp[x][y + 1][z] + pr * pdis) % MOD
    e = 0
    for x in range(m + 1):
        for y in range(m - x + 1):
            for z in range(x + 1):
                e = (e + dp[x][y][z] * (wi + z)) % MOD
    ans[idx] = e

# dislikes
for idx in dislikes:
    wi = w[idx]
    dp = [[[0] * (wi + 1) for _ in range(m + 1)] for _ in range(m + 1)]
    dp[0][0][0] = 1
    for x in range(m + 1):
        for y in range(m - x + 1):
            tot = P + Q + x - y
            if tot == 0:
                continue
            invt = INV[tot]
            plike = (P + x) * invt % MOD
            pdis = (Q - y) * invt % MOD if Q > y else 0
            for z in range(min(y, wi) + 1):
                pr = dp[x][y][z]
                if pr == 0:
                    continue
                if x + y == m:
                    continue
                # pick like
                dp[x + 1][y][z] = (dp[x + 1][y][z] + pr * plike) % MOD
                # pick dis
                if Q > y:
                    pthis = (wi - z) * INV[Q - y] % MOD if Q > y else 0
                    if z < wi:
                        dp[x][y + 1][z + 1] = (dp[x][y + 1][z + 1] + pr * pdis % MOD * pthis) % MOD
                    dp[x][y + 1][z] = (dp[x][y + 1][z] + pr * pdis % MOD * (1 - pthis + MOD)) % MOD
    e = 0
    for x in range(m + 1):
        for y in range(m - x + 1):
            for z in range(min(y, wi) + 1):
                e = (e + dp[x][y][z] * (wi - z)) % MOD
    ans[idx] = e

