def is_valid(s):
    bal = 0
    for c in s:
        if c == '(':
            bal += 1
        else:
            bal -= 1
        if bal < 0:
            return False
    return bal == 0

def main():
    data = sys.stdin.read().split()
    n = int(data[0])
    s = data[1]
    if n % 2 != 0:
        print("No")
        return
    opens = s.count('(')
    if opens != n - opens:
        print("No")
        return
    if is_valid(s):
        print("Yes")
        return
    # Find first unmatched ')'
    stack = 0
    first_close = -1
    for i, c in enumerate(s):
        if c == '(':
            stack += 1
        else:
            if stack == 0:
                first_close = i
                break
            stack -= 1
    if first_close != -1:
        news = s[:first_close] + s[first_close+1:] + ')'
        if is_valid(news):
            print("Yes")
            return
    # Find last unmatched '('
    stack = []
    for i, c in enumerate(s):
        if c == '(':
            stack.append(i)
        else:
            if stack:
                stack.pop()
    if stack:
        last_open = stack[-1]
        news = '(' + s[:last_open] + s[last_open+1:]
        if is_valid(news):
            print("Yes")
            return
    print("No")

