INF = 10**18

def main():
    n = int(sys.stdin.readline())
    a = list(map(int, sys.stdin.readline().split()))
    maxk = (n + 1) // 2
    dp = [[INF] * (maxk + 1) for _ in range(n)]
    # running min of dp[p][j] + right_cost(p) for p that can be used
    runmin = [INF] * (maxk + 1)

    for i in range(n):
        # place first house at i
        cost = 0
        if i > 0:
            cost = max(0, a[i - 1] - a[i] + 1)
        dp[i][1] = cost

        if i >= 2:
            # from p = i-2
            shared = max(0, a[i - 1] - min(a[i - 2], a[i]) + 1)
            for j in range(2, maxk + 1):
                if dp[i - 2][j - 1] < INF:
                    dp[i][j] = min(dp[i][j], dp[i - 2][j - 1] + shared)
            # from p <= i-3
            leftc = max(0, a[i - 1] - a[i] + 1) if i > 0 else 0
            for j in range(2, maxk + 1):
                if runmin[j - 1] < INF:
                    dp[i][j] = min(dp[i][j], runmin[j - 1] + leftc)

        # update runmin with this i if it can be a previous p later (needs right neighbor)
        if i + 1 < n:
            rc = max(0, a[i + 1] - a[i] + 1)
            for j in range(1, maxk + 1):
                if dp[i][j] < INF:
                    runmin[j] = min(runmin[j], dp[i][j] + rc)

    ans = [INF] * (maxk + 1)
    for i in range(n):
        rc = max(0, a[i + 1] - a[i] + 1) if i + 1 < n else 0
        for j in range(1, maxk + 1):
            if dp[i][j] < INF:
                ans[j] = min(ans[j], dp[i][j] + rc)

    print(' '.join(str(ans[j]) for j in range(1, maxk + 1)))

