import sys

def rotate(p, theta):
    x, y = p
    c, s = math.cos(theta), math.sin(theta)
    return (x * c - y * s, x * s + y * c)

def inside(P, A, B):
    return (B[0] - A[0]) * (P[1] - A[1]) - (B[1] - A[1]) * (P[0] - A[0]) >= -1e-12

def intersect(P, Q, A, B):
    dx, dy = Q[0] - P[0], Q[1] - P[1]
    da, db = B[0] - A[0], B[1] - A[1]
    denom = dx * db - dy * da
    if abs(denom) < 1e-15:
        return Q
    t = ((A[0] - P[0]) * db - (A[1] - P[1]) * da) / denom
    return (P[0] + t * dx, P[1] + t * dy)

def clip(subject, clipper):
    output = subject[:]
    nclip = len(clipper)
    for i in range(nclip):
        input_poly = output
        output = []
        A = clipper[i - 1]
        B = clipper[i]
        n = len(input_poly)
        if n == 0:
            break
        for j in range(n):
            P = input_poly[j - 1]
            Q = input_poly[j]
            Qin = inside(Q, A, B)
            Pin = inside(P, A, B)
            if Qin:
                if not Pin:
                    output.append(intersect(P, Q, A, B))
                output.append(Q)
            elif Pin:
                output.append(intersect(P, Q, A, B))
    return output

def polygon_area(poly):
    n = len(poly)
    if n < 3:
        return 0.0
    s = 0.0
    for i in range(n):
        x1, y1 = poly[i]
        x2, y2 = poly[(i + 1) % n]
        s += x1 * y2 - x2 * y1
    return abs(s) / 2.0

