import math
import sys

def rotate_point(p, ang):
    c, s = math.cos(ang), math.sin(ang)
    return (p[0]*c - p[1]*s, p[0]*s + p[1]*c)

def inside(p, a, b):
    return (b[0]-a[0])*(p[1]-a[1]) - (b[1]-a[1])*(p[0]-a[0]) >= -1e-12

def intersection(p1, p2, a, b):
    dx, dy = p2[0]-p1[0], p2[1]-p1[1]
    da, db = b[0]-a[0], b[1]-a[1]
    denom = dx*db - dy*da
    if abs(denom) < 1e-15:
        return p1
    t = ((a[0]-p1[0])*db - (a[1]-p1[1])*da) / denom
    return (p1[0] + t*dx, p1[1] + t*dy)

def clip(subject, clipper):
    out = subject[:]
    for i in range(len(clipper)):
        a = clipper[i]
        b = clipper[(i+1)%len(clipper)]
        inp = out
        out = []
        if not inp:
            break
        s = inp[-1]
        for e in inp:
            if inside(e, a, b):
                if not inside(s, a, b):
                    out.append(intersection(s, e, a, b))
                out.append(e)
            elif inside(s, a, b):
                out.append(intersection(s, e, a, b))
            s = e
    return out

def polygon_area(poly):
    n = len(poly)
    if n < 3:
        return 0.0
    a = 0.0
    for i in range(n):
        j = (i+1)%n
        a += poly[i][0]*poly[j][1] - poly[j][0]*poly[i][1]
    return abs(a)/2.0

