        print("%.9f" % (w * h))
        return
    ang = math.radians(alpha)
    r1 = [(w/2, h/2), (-w/2, h/2), (-w/2, -h/2), (w/2, -h/2)]
    r2 = [rotate_point(p, ang) for p in r1]
    inter = clip(r1, r2)
    print("%.9f" % polygon_area(inter))

