import sys
from functools import lru_cache

def main():
    n = int(sys.stdin.readline())
    c = list(map(int, sys.stdin.readline().split()))
    if n == 1:
        print("YES" if c[0] == 1 else "NO")
        return
    roots = [i for i in range(n) if c[i] == n]
    if len(roots) != 1:
        print("NO")
        return
    root = roots[0]
    full = (1 << n) - 1
    descendants = full ^ (1 << root)
    if bin(descendants).count('1') != n - 1:
        print("NO")
        return

    @lru_cache(None)
    def is_tree(rt, mask):
        if c[rt] != bin(mask).count('1') + 1:
            return False
        if c[rt] == 1:
            return mask == 0
        return can_split(mask, 0, 0)

    def can_split(mask, prev_sz, num):
        if mask == 0:
            return num >= 2
        # pick next child root as the highest bit to canonicalize a bit
        # try every possible child root in the mask
        m = mask
        while m:
            j = (m & -m).bit_length() - 1
            m ^= 1 << j
            sz = c[j]
            if sz > bin(mask).count('1') or sz < 1:
                continue
            if sz > prev_sz and prev_sz != 0:
                continue  # keep non-increasing sizes
            need = sz - 1
            # enumerate submasks of (mask ^ (1<<j)) with popcount == need
            rest = mask ^ (1 << j)
            sub = rest
            while True:
                if bin(sub).count('1') == need:
                    if is_tree(j, sub):
                        if can_split(rest ^ sub, sz, num + 1):
                            return True
                if sub == 0:
                    break
                sub = (sub - 1) & rest
        return False

    print("YES" if is_tree(root, descendants) else "NO")

