from functools import lru_cache

def main():
    n = int(sys.stdin.readline())
    c = list(map(int, sys.stdin.readline().split()))
    if n == 1:
        print("YES" if c[0] == 1 else "NO")
        return
    internals = [x for x in c if x > 1]
    m = len(internals)
    leaves = n - m
    if c.count(n) != 1 or n not in internals:
        print("NO")
        return
    # m <= 11
    is_tree = [[False] * (leaves + 1) for _ in range(1 << m)]
    is_forest = [[False] * (leaves + 1) for _ in range(1 << m)]
    is_forest[0][0] = True
    for L in range(1, leaves + 1):
        is_forest[0][L] = True  # L single-node trees
    # bottom-up by total nodes
    for tot in range(1, n + 1):
        for mask in range(1 << m):
            pc = bin(mask).count("1")
            if pc > tot:
                continue
            L = tot - pc
            if L > leaves or L < 0:
                continue
            # compute is_tree[mask][L]
            possible_roots = []
            for i in range(m):
                if (mask & (1 << i)) and internals[i] == tot:
                    possible_roots.append(i)
            if len(possible_roots) == 1:
                i = possible_roots[0]
                mask2 = mask ^ (1 << i)
                rem_nodes = tot - 1
                if rem_nodes >= 2 and is_forest[mask2][L]:
                    # need a partition of rem into k>=2
                    # check existence of a non-full first tree
                    ge2 = False
                    if mask2 == 0:
                        ge2 = L >= 2
                    else:
                        sub = mask2
                        while True:
                            for l in range(L + 1):
                                if is_tree[sub][l] and is_forest[mask2 ^ sub][L - l]:
                                    if sub != mask2 or l != L:
                                        ge2 = True
                                        break
                            if ge2:
                                break
                            if sub == 0:
                                break
                            sub = (sub - 1) & mask2
                    if ge2:
                        is_tree[mask][L] = True
            # compute is_forest[mask][L]
            if mask == 0:
                continue
            # can we partition into >=1 trees
            found = is_tree[mask][L]  # k=1
            if not found:
                sub = mask
                while True:
                    for l in range(L + 1):
                        if is_tree[sub][l] and is_forest[mask ^ sub][L - l]:
                            found = True
                            break
                    if found:
                        break
                    if sub == 0:
                        break
                    sub = (sub - 1) & mask
            is_forest[mask][L] = found
    full = (1 << m) - 1
    print("YES" if is_tree[full][leaves] else "NO")

