sys.setrecursionlimit(1000000)

def main():
    n, m = map(int, sys.stdin.readline().split())
    r = list(map(int, sys.stdin.readline().split()))
    rooms = [[] for _ in range(n)]
    for i in range(m):
        data = list(map(int, sys.stdin.readline().split()))
        for rm in data[1:]:
            rooms[rm-1].append(i)

    N = 2 * m
    g = [[] for _ in range(N)]
    gt = [[] for _ in range(N)]

    def add_imp(u, v):
        g[u].append(v)
        gt[v].append(u)

    def add_eq(a, b):  # a == b
        # a -> b, ~a -> ~b, b -> a, ~b -> ~a
        add_imp(2*a+1, 2*b+1)
        add_imp(2*a, 2*b)
        add_imp(2*b+1, 2*a+1)
        add_imp(2*b, 2*a)

    def add_neq(a, b):  # a != b
        # a -> ~b, ~a -> b, b -> ~a, ~b -> a
        add_imp(2*a+1, 2*b)
        add_imp(2*a, 2*b+1)
        add_imp(2*b+1, 2*a)
        add_imp(2*b, 2*a+1)

    for i in range(n):
        a, b = rooms[i]
        need = 1 - r[i]
        if need == 0:
            add_eq(a, b)
        else:
            add_neq(a, b)

    vis = [False] * N
    order = []

    def dfs1(u):
        vis[u] = True
        for v in g[u]:
            if not vis[v]:
                dfs1(v)
        order.append(u)

    for i in range(N):
        if not vis[i]:
            dfs1(i)

    comp = [-1] * N
    cid = 0

    def dfs2(u, c):
        comp[u] = c
        for v in gt[u]:
            if comp[v] == -1:
                dfs2(v, c)

    for u in reversed(order):
        if comp[u] == -1:
            dfs2(u, cid)
            cid += 1

    for i in range(m):
        if comp[2*i] == comp[2*i+1]:
            print("NO")
            return
    print("YES")

