    P = 0
    lo = max(1, S - K)
    hi = min(K, S - 1)
    for a in range(lo, hi + 1):
        if a < S - a:
            P += 1
    R = K - P
    res = 0
    for k in range(P + 1):
        if N - k < 0:
            break
        res = (res + binom(P, k) * binom(N - k + R - 1, R - 1)) % MOD
    ans.append(res)
