    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    N = int(next(it))
    M = int(next(it))
    X = int(next(it))
    books = []
    for _ in range(N):
        C = int(next(it))
        A = [int(next(it)) for _ in range(M)]
        books.append((C, A))
    min_cost = float('inf')
    for k in range(1, N+1):
        for combo in combinations(range(N), k):
            cost = 0
            und = [0] * M
            for i in combo:
                cost += books[i][0]
                for j in range(M):
                    und[j] += books[i][1][j]
            if all(u >= X for u in und):
                min_cost = min(min_cost, cost)
    print(min_cost if min_cost != float('inf') else -1)

