import sys
import itertools

def orient(a, b, c):
    return (b[0] - a[0]) * (c[1] - a[1]) - (b[1] - a[1]) * (c[0] - a[0])

def segments_cross(p1, p2, q1, q2):
    o1 = orient(p1, p2, q1)
    o2 = orient(p1, p2, q2)
    o3 = orient(q1, q2, p1)
    o4 = orient(q1, q2, p2)
    return o1 * o2 < 0 and o3 * o4 < 0

def main():
    data = sys.stdin.read().split()
    if not data:
        return
    R = int(data[0])
    B = int(data[1])
    idx = 2
    ships = []
    for _ in range(R):
        x = int(data[idx]); y = int(data[idx+1]); idx += 2
        ships.append((x, y))
    bases = []
    for _ in range(B):
        x = int(data[idx]); y = int(data[idx+1]); idx += 2
        bases.append((x, y))
    if R != B:
        print("No")
        return
    n = R
    for perm in itertools.permutations(range(n)):
        good = True
        for i in range(n):
            for j in range(i+1, n):
                if segments_cross(ships[i], bases[perm[i]], ships[j], bases[perm[j]]):
                    good = False
                    break
            if not good:
                break
        if good:
            print("Yes")
            return
    print("No")

if __name__ == "__main__":
    main()

import sys
from itertools import permutations

def ccw(A, B, C):
    return (C[1] - A[1]) * (B[0] - A[0]) > (B[1] - A[1]) * (C[0] - A[0])

def intersect(A, B, C, D):
    return ccw(A, C, D) != ccw(B, C, D) and ccw(A, B, C) != ccw(A, B, D)

