sys.setrecursionlimit(10000)

def main():
    n, m, s = map(int, sys.stdin.readline().split())
    s -= 1
    g = [[] for _ in range(n)]
    rg = [[] for _ in range(n)]
    for _ in range(m):
        u, v = map(int, sys.stdin.readline().split())
        u -= 1
        v -= 1
        g[u].append(v)
        rg[v].append(u)

    visited = [False] * n
    order = []
    def dfs1(u):
        visited[u] = True
        for v in g[u]:
            if not visited[v]:
                dfs1(v)
        order.append(u)

    for i in range(n):
        if not visited[i]:
            dfs1(i)

    comp = [-1] * n
    cid = 0
    def dfs2(u):
        comp[u] = cid
        for v in rg[u]:
            if comp[v] == -1:
                dfs2(v)

    for u in reversed(order):
        if comp[u] == -1:
            dfs2(u)
            cid += 1

    if cid == 1:
        print(0)
        return

    indeg = [0] * cid
    for u in range(n):
        for v in g[u]:
            if comp[u] != comp[v]:
                indeg[comp[v]] += 1

    reach = [False] * cid
    from collections import deque
    q = deque([comp[s]])
    reach[comp[s]] = True
    adjc = [[] for _ in range(cid)]
    for u in range(n):
        for v in g[u]:
            if comp[u] != comp[v]:
                adjc[comp[u]].append(comp[v])
    while q:
        c = q.popleft()
        for nc in adjc[c]:
            if not reach[nc]:
                reach[nc] = True
                q.append(nc)

    ans = 0
    for c in range(cid):
        if not reach[c] and indeg[c] == 0:
            ans += 1
    print(ans)

