def main():
    n, m, s = map(int, sys.stdin.readline().split())
    s -= 1
    adj = [[] for _ in range(n)]
    for _ in range(m):
        u, v = map(int, sys.stdin.readline().split())
        adj[u-1].append(v-1)

    visited = [False] * n
    stack = [s]
    visited[s] = True
    while stack:
        u = stack.pop()
        for v in adj[u]:
            if not visited[v]:
                visited[v] = True
                stack.append(v)

    U = [i for i in range(n) if not visited[i]]
    if not U:
        print(0)
        return

    idx = {u: i for i, u in enumerate(U)}
    k = len(U)
    adjU = [[] for _ in range(k)]
    radjU = [[] for _ in range(k)]
    for u in U:
        iu = idx[u]
        for v in adj[u]:
            if v in idx:
                iv = idx[v]
                adjU[iu].append(iv)
                radjU[iv].append(iu)

    vis = [False] * k
    order = []
    def dfs1(u):
        vis[u] = True
        for v in adjU[u]:
            if not vis[v]:
                dfs1(v)
        order.append(u)
    for i in range(k):
        if not vis[i]:
            dfs1(i)

    comp = [-1] * k
    cid = 0
    def dfs2(u):
        comp[u] = cid
        for v in radjU[u]:
            if comp[v] == -1:
                dfs2(v)
    for u in reversed(order):
        if comp[u] == -1:
            dfs2(u)
            cid += 1

    indeg = [0] * cid
    for u in range(k):
        for v in adjU[u]:
            if comp[u] != comp[v]:
                indeg[comp[v]] += 1

    sources = sum(1 for d in indeg if d == 0)
    print(sources)

