from collections import defaultdict

def main():
    input = sys.stdin.read().split()
    idx = 0
    n = int(input[idx]); idx += 1
    m = int(input[idx]); idx += 1
    k = int(input[idx]); idx += 1
    a = [[0]*m for _ in range(n)]
    for i in range(n):
        for j in range(m):
            a[i][j] = int(input[idx]); idx += 1
    if n == 1 and m == 1:
        print(1 if a[0][0] == k else 0)
        return
    total_steps = n + m - 2
    half = total_steps // 2
    from_start = [[defaultdict(int) for _ in range(m)] for _ in range(n)]
    def dfs_start(x, y, xor_val, steps):
        xor_val ^= a[x][y]
        if steps == half:
            from_start[x][y][xor_val] += 1
            return
        if x + 1 < n:
            dfs_start(x + 1, y, xor_val, steps + 1)
        if y + 1 < m:
            dfs_start(x, y + 1, xor_val, steps + 1)
    dfs_start(0, 0, 0, 0)
    from_end = [[defaultdict(int) for _ in range(m)] for _ in range(n)]
    rem = total_steps - half
    def dfs_end(x, y, xor_val, steps):
        if steps == rem:
            from_end[x][y][xor_val] += 1
            return
        xor_val ^= a[x][y]
        if x - 1 >= 0:
            dfs_end(x - 1, y, xor_val, steps + 1)
        if y - 1 >= 0:
            dfs_end(x, y - 1, xor_val, steps + 1)
    dfs_end(n-1, m-1, 0, 0)
    ans = 0
    for i in range(n):
        for j in range(m):
            if (i + j) == half:
                for xs, cnts in from_start[i][j].items():
                    need = xs ^ k
                    ans += cnts * from_end[i][j][need]
    print(ans)

