import sys

def sum_len_upto(n):
    if n <= 0:
        return 0
    total_digits = 0
    weighted = 0
    start = 1
    d = 1
    while start <= n:
        end = min(n, 10**d - 1)
        cnt = end - start + 1
        total_digits += d * cnt
        s = (start + end) * cnt // 2
        weighted += d * s
        start = end + 1
        d += 1
    return (n + 1) * total_digits - weighted

def concat_len(m):
    if m <= 0:
        return 0
    res = 0
    start = 1
    d = 1
    while start <= m:
        end = min(m, 10**d - 1)
        cnt = end - start + 1
        res += d * cnt
        start = end + 1
        d += 1
    return res

def digit_in_concat(p, n):
    lo, hi = 1, n
    while lo < hi:
        mid = (lo + hi) // 2
        if concat_len(mid) >= p:
            hi = mid
        else:
            lo = mid + 1
    m = lo
    prev = concat_len(m - 1)
    s = str(m)
    return s[p - prev - 1]

def solve_query(k):
    lo, hi = 1, 2 * 10**9
    while lo < hi:
        mid = (lo + hi) // 2
        if sum_len_upto(mid) >= k:
            hi = mid
        else:
            lo = mid + 1
    n = lo
    p = k - sum_len_upto(n - 1)
    return digit_in_concat(p, n)

def main():
    data = sys.stdin.read().split()
    q = int(data[0])
    res = []
    for i in range(1, q + 1):
        k = int(data[i])
        res.append(solve_query(k))
    sys.stdout.write('\n'.join(res) + '\n')

if __name__ == "__main__":
    main()

