class Fenwick:
    def __init__(self, n):
        self.n = n
        self.bit = [0] * (n + 1)

    def add(self, i, delta):
        i += 1
        while i <= self.n:
            self.bit[i] += delta
            i += i & -i

    def sum(self, i):
        s = 0
        i += 1
        while i > 0:
            s += self.bit[i]
            i -= i & -i
        return s

    def find_first_ge(self, t):
        # smallest pos >= t with positive freq, or -1
        if t >= self.n:
            return -1
        pref = self.sum(t - 1) if t > 0 else 0
        total = self.sum(self.n - 1)
        if total == pref:
            return -1
        # binary search smallest pos >= t with sum(pos) > pref
        lo, hi = t, self.n - 1
        while lo < hi:
            mid = (lo + hi) // 2
            if self.sum(mid) > pref:
                hi = mid
            else:
                lo = mid + 1
        return lo

