class Fenwick:
    def __init__(self, n):
        self.n = n
        self.t = [0] * (n + 1)
    def add(self, i, v):
        i += 1
        while i <= self.n:
            self.t[i] += v
            i += i & -i
    def sum(self, i):
        s = 0
        i += 1
        while i > 0:
            s += self.t[i]
            i -= i & -i
        return s
    def find_first(self, start):
        # find smallest pos >= start with freq >0, or -1
        lo, hi = start, self.n - 1
        if self.sum(hi) - (self.sum(start-1) if start else 0) == 0:
            return -1
        while lo < hi:
            mid = (lo + hi) // 2
            if self.sum(mid) - (self.sum(start-1) if start else 0) > 0:
                hi = mid
            else:
                lo = mid + 1
        return lo

