class DSU:
    def __init__(self, n):
        self.p = list(range(n))
        self.r = [0] * n
    def find(self, x):
        while self.p[x] != x:
            self.p[x] = self.p[self.p[x]]
            x = self.p[x]
        return x
    def union(self, x, y):
        x, y = self.find(x), self.find(y)
        if x == y:
            return False
        if self.r[x] < self.r[y]:
            x, y = y, x
        self.p[y] = x
        if self.r[x] == self.r[y]:
            self.r[x] += 1
        return True

