def get_primes(x):
    primes = []
    if x % 2 == 0:
        primes.append(2)
        while x % 2 == 0:
            x //= 2
    i = 3
    while i * i <= x:
        if x % i == 0:
            primes.append(i)
            while x % i == 0:
                x //= i
        i += 2
    if x > 1:
