def sum_v(n, p):
    s = 0
    pp = p
    while pp <= n:
        s += n // pp
        if pp > n // p:
            break
        pp *= p
    return s

def modpow(a, b, mod):
    res = 1
    a %= mod
    while b:
        if b & 1:
            res = res * a % mod
        a = a * a % mod
        b >>= 1
    return res

