PHI = MOD - 1

def mat_mult(A, B, mod):
    C = [[0]*3 for _ in range(3)]
    for i in range(3):
        for k in range(3):
            if A[i][k]:
                for j in range(3):
                    C[i][j] = (C[i][j] + A[i][k] * B[k][j]) % mod
    return C

def mat_pow(M, exp, mod):
    res = [[1 if i==j else 0 for j in range(3)] for i in range(3)]
    while exp:
        if exp & 1:
            res = mat_mult(res, M, mod)
        M = mat_mult(M, M, mod)
        exp >>= 1
    return res

def get_seq(n, s1, s2, s3, mod):
    if n == 1:
        return s1
    if n == 2:
        return s2
    if n == 3:
        return s3
    M = [[1,1,1],[1,0,0],[0,1,0]]
    P = mat_pow(M, n-3, mod)
    return (P[0][0]*s3 + P[0][1]*s2 + P[0][2]*s1) % mod

