def simulate(start, n, m):
    counts = [n, m]
    if counts[start] == 0:
        return float('inf')
    counts[start] -= 1
    last = start
    groups = 1
    total = n + m
    is_vasya = True
    for _ in range(total - 1):
        other = 1 - last
        if is_vasya:
            if counts[other] > 0:
                counts[other] -= 1
                last = other
                groups += 1
            else:
                counts[last] -= 1
        else:
            if counts[last] > 0:
                counts[last] -= 1
            else:
                counts[other] -= 1
                last = other
                groups += 1
        is_vasya = not is_vasya
    return groups

def main():
    n, m = map(int, sys.stdin.readline().split())
