from math import gcd
from functools import lru_cache

MOD = 10**9 + 7

def egcd(a, b):
    if a == 0:
        return b, 0, 1
    g, x, y = egcd(b % a, a)
    return g, y - (b // a) * x, x

def modinv_solve(aa, mm, cc):
    # solve aa * k ≡ cc (mod mm), return (k0, period) or None
    g, x, _ = egcd(aa % mm, mm)
    if cc % g != 0:
        return None
    mmg = mm // g
    x = (x * (cc // g)) % mmg
    return x, mmg

def main():
    t, a, b = map(int, sys.stdin.read().split())
    if t == a:
        if b != a:
            print(0)
        else:
            print("inf" if t == 1 else 2)
        return
    if t > a:
        print(1 if a == b else 0)
        return
    # now t < a, a >= 2
    @lru_cache(None)
    def rec(x, y):
        if x == 0 and y == 0:
            return 1
        if x < 0 or y < 0:
            return 0
        r = x % t
        c = (y - r) % a
        sol = modinv_solve(t, a, c)
        if sol is None:
            return 0
        k0, period = sol
        q = x // t
        res = 0
        k = k0
        if k < 0:
            k += ((-k + period - 1) // period) * period
        while k <= q:
            d = r + k * t
            if d > y:
                break
            nx = q - k
            ny = (y - d) // a
            if (y - d) % a == 0:
                res = (res + rec(nx, ny)) % MOD
            k += period
        return res
    print(rec(a, b) % MOD)

if __name__ == "__main__":
    main()

