def extgcd(p, q):
    if q == 0:
        return p, 1, 0
    g, x, y = extgcd(q, p % q)
    return g, y, x - (p // q) * y

def rec(rest_t, rest_a, t, a):
    if rest_t == 0:
        return 1 if rest_a == 0 else 0
    rt = rest_t % t
    ra = rest_a % a
    g, x, y = extgcd(t, a)
    if (ra - rt) % g != 0:
        return 0
    t_div = t // g
    a_div = a // g
    diff = (ra - rt) // g
    inv = x % a_div
    u0 = (diff * inv) % a_div
    c0 = rt + t * u0
    step = t // g * a
    mn = min(rest_t, rest_a)
    if c0 < 0:
        k = (-c0 + step - 1) // step
        c0 += k * step
    res = 0
    for _ in range(3):
        if c0 > mn:
            break
        if (rest_t - c0) % t == 0 and (rest_a - c0) % a == 0:
            nt = (rest_t - c0) // t
            na = (rest_a - c0) // a
            res += rec(nt, na, t, a)
        c0 += step
    return res

