import sys
MOD = 998244353

def main():
    n, k = map(int, sys.stdin.readline().split())
    if k == 0:
        fact = 1
        for i in range(1, n + 1):
            fact = fact * i % MOD
        print(fact)
        return
    if k >= n:
        print(0)
        return
    m = n - k
    N = n
    fact = [1] * (N + 1)
    for i in range(1, N + 1):
        fact[i] = fact[i - 1] * i % MOD
    invfact = [1] * (N + 1)
    invfact[N] = pow(fact[N], MOD - 2, MOD)
    for i in range(N, 0, -1):
        invfact[i - 1] = invfact[i] * i % MOD
    def binom(a, b):
        if b < 0 or b > a:
            return 0
        return fact[a] * invfact[b] % MOD * invfact[a - b] % MOD
    s = 0
    for j in range(m + 1):
        term = binom(m, j) * pow(j, n, MOD) % MOD
        if (m - j) % 2 == 1:
            term = MOD - term
        s = (s + term) % MOD
    ans = 2 * binom(n, m) % MOD * s % MOD
    print(ans)

