from collections import deque

def state_from_grid(grid):
    return ''.join(grid)

def neighbors(s):
    pos = s.index('X')
    dirs = []
    if pos % 2 == 0:
        dirs.append(pos + 1)
    else:
        dirs.append(pos - 1)
    if pos < 2:
        dirs.append(pos + 2)
    else:
        dirs.append(pos - 2)
    res = []
    for d in dirs:
        lst = list(s)
        lst[pos], lst[d] = lst[d], lst[pos]
        res.append(''.join(lst))
    return res

def reachable(start):
    vis = set()
    q = deque([start])
    vis.add(start)
    while q:
        cur = q.popleft()
        for nxt in neighbors(cur):
            if nxt not in vis:
                vis.add(nxt)
                q.append(nxt)
    return vis

