@lru_cache(None)
def dp(pos, tightL, tightR, started, xtight):
    if pos == 60:
        return 1 if started else 0
    res = 0
    lo = int(bitsL[pos]) if tightL else 0
    hi = int(bitsR[pos]) if tightR else 1
    for yb in range(lo, hi + 1):
        ntightL = tightL and yb == lo
        ntightR = tightR and yb == hi
        if not started:
            if yb == 0:
                res += dp(pos + 1, ntightL, ntightR, False, xtight)
            else:
                # must set xb = 1
                xb = 1
                nxl = xtight and xb == int(bitsL[pos])
                if not xtight or xb >= int(bitsL[pos]):
                    res += dp(pos + 1, ntightL, ntightR, True, nxl)
        else:
            if yb == 0:
                xb = 0
                if not xtight or xb >= int(bitsL[pos]):
                    nxl = xtight and xb == int(bitsL[pos])
                    res += dp(pos + 1, ntightL, ntightR, True, nxl)
            else:
                for xb in (0, 1):
