MOD = 10**9 + 7

def solve(L, R):
    bits = 60
    Lbits = [(L >> i) & 1 for i in range(bits)]
    Rbits = [(R >> i) & 1 for i in range(bits)]
    Lbits.reverse()
    Rbits.reverse()

    @lru_cache(None)
    def dp(pos, tightLx, tightRx, tightLy, tightRy, started):
        if pos == bits:
            return 1 if started else 0
        res = 0
        lx = Lbits[pos] if tightLx else 0
        hx = Rbits[pos] if tightRx else 1
        ly = Lbits[pos] if tightLy else 0
        hy = Rbits[pos] if tightRy else 1
        for bx in range(lx, hx + 1):
            for by in range(ly, hy + 1):
                if bx > by:
                    continue
                nstarted = started
                if not started:
                    if bx == 1 and by == 1:
                        nstarted = 1
                    elif bx == 1 or by == 1:
                        continue
                ntlx = tightLx and (bx == Lbits[pos])
                ntrx = tightRx and (bx == Rbits[pos])
                ntly = tightLy and (by == Lbits[pos])
                ntry = tightRy and (by == Rbits[pos])
                res += dp(pos + 1, ntlx, ntrx, ntly, ntry, nstarted)
                if res >= MOD:
                    res -= MOD
        return res

    return dp(0, True, True, True, True, 0)

