def merge(blocks):
    if not blocks:
        return []
    merged = [blocks[0]]
    for l, c in blocks[1:]:
        if c == merged[-1][1]:
            merged[-1] = (merged[-1][0] + l, c)
        else:
            merged.append((l, c))
    return merged

def kmp_search(text, pattern):
    if not pattern:
        return list(range(len(text) + 1))
    n, m = len(text), len(pattern)
    pi = [0] * m
    j = 0
    for i in range(1, m):
        while j > 0 and pattern[i] != pattern[j]:
            j = pi[j - 1]
        if pattern[i] == pattern[j]:
            j += 1
        pi[i] = j
    res = []
    j = 0
    for i in range(n):
        while j > 0 and text[i] != pattern[j]:
            j = pi[j - 1]
        if text[i] == pattern[j]:
            j += 1
        if j == m:
            res.append(i - m + 1)
            j = pi[j - 1]
    return res

