def kmp_prefix(pat):
    m = len(pat)
    pi = [0] * m
    k = 0
    for i in range(1, m):
        while k > 0 and pat[i] != pat[k]:
            k = pi[k - 1]
        if pat[i] == pat[k]:
            k += 1
        pi[i] = k
    return pi

def find_occurrences(text, pat):
    if not pat:
        return list(range(len(text) + 1))
    pi = kmp_prefix(pat)
    res = []
    k = 0
    for i, t in enumerate(text):
        while k > 0 and t != pat[k]:
            k = pi[k - 1]
        if t == pat[k]:
            k += 1
        if k == len(pat):
            res.append(i - len(pat) + 1)
            k = pi[k - 1]
    return res

