    # sliding window minimums of every window of size c
    mins = [0] * n
    dq = deque()
    for i in range(n):
        while dq and dq[0] <= i - c:
            dq.popleft()
        while dq and a[dq[-1]] >= a[i]:
            dq.pop()
        dq.append(i)
        if i >= c - 1:
            mins[i] = a[dq[0]]
    dp = [0] * (n + 1)
    for i in range(1, n + 1):
        dp[i] = dp[i - 1]
        if i >= c:
            dp[i] = max(dp[i], dp[i - c] + mins[i - 1])
    print(total - dp[n])

