    if n == 1:
        return b[0], b[0]
    if n == 2:
        v = -b[0] - b[1]
        return v, v
    if n == 3:
        v1 = b[0] + b[1] - b[2]
        v2 = -b[0] + b[1] + b[2]
        return min(v1, v2), max(v1, v2)
    # n == 4
    s = sum(b)
    poss = [s] + [2 * x - s for x in b]
    return min(poss), max(poss)

