def can(x, a, k):
    n = len(a)
    # Case 1: all odd positions <= x (1-based)
    # Greedy take earliest possible
    taken = 0
    need_odd = True
    for val in a:
        if need_odd:
            if val <= x:
                taken += 1
                need_odd = False
        else:
            taken += 1
            need_odd = True
        if taken >= k:
            return True
    # Case 2: all even positions <= x
    taken = 0
    need_even = False  # first is odd, anything
    for val in a:
        if need_even:
            if val <= x:
                taken += 1
                need_even = False
        else:
            taken += 1
            need_even = True
        if taken >= k:
            return True
    return False

