from math import factorial

def count_exponents(n):
    primes = []
    is_prime = [True] * (n + 1)
    for i in range(2, n + 1):
        if is_prime[i]:
            primes.append(i)
            for j in range(i * i, n + 1, i):
                is_prime[j] = False
    exps = []
    for p in primes:
        e = 0
        pp = p
        while pp <= n:
            e += n // pp
            pp *= p
        exps.append(e)
    return exps

def solve(n):
    if n < 10:
        return 0
    exps = count_exponents(n)
    m = len(exps)
    cnt = 0
    # p^74
    for e in exps:
        if e >= 74:
            cnt += 1
    # p^{24} * q^2
    for i in range(m):
        for j in range(m):
            if i != j and exps[i] >= 24 and exps[j] >= 2:
                cnt += 1
    # p^{14} * q^4
    for i in range(m):
        for j in range(m):
            if i != j and exps[i] >= 14 and exps[j] >= 4:
                cnt += 1
    # p^4 * q^4 * r^2
    for i in range(m):
        for j in range(i + 1, m):
            for k in range(m):
                if k != i and k != j and exps[i] >= 4 and exps[j] >= 4 and exps[k] >= 2:
                    cnt += 1
    return cnt

