import sys
from collections import defaultdict

MOD = 10**9 + 7
INF = 10**18

class SegTree:
    def __init__(self, n):
        self.n = n
        self.maxin = [-INF] * (4 * n)
        self.mindp = [INF] * (4 * n)
        self.cnt = [0] * (4 * n)

    def _upd(self, v):
        self.maxin[v] = max(self.maxin[2*v], self.maxin[2*v+1])
        a, b = self.mindp[2*v], self.mindp[2*v+1]
        if a < b:
            self.mindp[v] = a
            self.cnt[v] = self.cnt[2*v]
        elif b < a:
            self.mindp[v] = b
            self.cnt[v] = self.cnt[2*v+1]
        else:
            self.mindp[v] = a
            self.cnt[v] = (self.cnt[2*v] + self.cnt[2*v+1]) % MOD

    def insert(self, v, tl, tr, pos, inn, dp, c):
        if tl == tr:
            self.maxin[v] = max(self.maxin[v], inn)
            if dp < self.mindp[v]:
                self.mindp[v] = dp
                self.cnt[v] = c
            elif dp == self.mindp[v]:
                self.cnt[v] = (self.cnt[v] + c) % MOD
            return
        tm = (tl + tr) // 2
        if pos <= tm:
            self.insert(2*v, tl, tm, pos, inn, dp, c)
        else:
            self.insert(2*v+1, tm+1, tr, pos, inn, dp, c)
        self._upd(v)

    def query_maxin(self, v, tl, tr, l, r):
        if l > r:
            return -INF
        if l == tl and r == tr:
            return self.maxin[v]
        tm = (tl + tr) // 2
        return max(self.query_maxin(2*v, tl, tm, l, min(r, tm)),
                   self.query_maxin(2*v+1, tm+1, tr, max(l, tm+1), r))

    def query_min(self, v, tl, tr, l, r):
        if l > r:
            return (INF, 0)
        if l == tl and r == tr:
            return (self.mindp[v], self.cnt[v])
        tm = (tl + tr) // 2
        p1 = self.query_min(2*v, tl, tm, l, min(r, tm))
        p2 = self.query_min(2*v+1, tm+1, tr, max(l, tm+1), r)
        if p1[0] < p2[0]:
            return p1
        if p2[0] < p1[0]:
            return p2
        return (p1[0], (p1[1] + p2[1]) % MOD)

def main():
    data = sys.stdin.read().split()
    n = int(data[0])
    dolls = []
    idx = 1
    all_outs = []
    max_in_all = 0
    for i in range(n):
        o = int(data[idx]); inn = int(data[idx+1]); idx += 2
        dolls.append((o, inn))
        all_outs.append(o)
        max_in_all = max(max_in_all, inn)
    unique = sorted(set(all_outs))
    m = len(unique)
    pos = {unique[i]: i for i in range(m)}
    st = SegTree(m)
    dolls.sort()
    dps = []
    cnts = []
    for o, inn in dolls:
        X = inn
        # find rightmost unique <= X
        lo, hi = 0, m-1
        rpos = -1
        while lo <= hi:
            mid = (lo + hi) // 2
            if unique[mid] <= X:
                rpos = mid
                lo = mid + 1
            else:
                hi = mid - 1
        M = -INF
        if rpos >= 0:
            M = st.query_maxin(1, 0, m-1, 0, rpos)
        # range out > M and out <= X i.e. first unique > M to rpos
        lo, hi = 0, m-1
        lpos = m
        while lo <= hi:
            mid = (lo + hi) // 2
            if unique[mid] > M:
                lpos = mid
                hi = mid - 1
            else:
                lo = mid + 1
        mn, cn = INF, 0
        if lpos <= rpos and rpos >= 0:
            mn, cn = st.query_min(1, 0, m-1, lpos, rpos)
        if mn == INF:
            dp = inn - o
            c = 1
        else:
            dp = mn + (inn - o)
            c = cn
        dps.append(dp)
        cnts.append(c)
        st.insert(1, 0, m-1, pos[o], inn, dp, c)
    min_extra = INF
    ans = 0
    for i, (o, inn) in enumerate(dolls):
        if o > max_in_all:
            extra = dps[i] + o
            if extra < min_extra:
                min_extra = extra
                ans = cnts[i]
            elif extra == min_extra:
                ans = (ans + cnts[i]) % MOD
    print(ans % MOD)

if __name__ == "__main__":
    main()

