def main():
    n, m = map(int, sys.stdin.readline().split())
    a = list(map(int, sys.stdin.readline().split()))
    b = list(map(int, sys.stdin.readline().split()))
    a.sort()
    b.sort()
    min_x = m
    for k in range(n + 1):
        xs = set()
        valid = True
        # wrapping part: a[n-k:] + x - m == b[:k]
        for i in range(k):
            x = (b[i] - a[n - k + i] + m) % m
            xs.add(x)
            if len(xs) > 1:
                valid = False
                break
        if not valid:
            continue
        # non-wrapping part: a[:n-k] + x == b[k:]
        for j in range(n - k):
            x = (b[k + j] - a[j] + m) % m
            xs.add(x)
            if len(xs) > 1:
                valid = False
                break
        if not valid or not xs:
            continue
        x = xs.pop()
        # check wrap conditions
        if k > 0:
            if a[n - k] + x < m:
                continue
        if k < n:
            if a[n - k - 1] + x >= m:
                continue
        if 0 <= x < m:
            min_x = min(min_x, x)
    print(min_x)

