import math

def complete_bits(n):
    if n <= 1:
        return 0
    h = n.bit_length() - 1
    p = 1 << h
    return (2 * p - n) * h + 2 * (n - p) * (h + 1)

def calc(n, a, b):
    ans = 0
    while n > 1:
        if (n - 2) * a <= b:
            ans += a * n * (n - 1) // 2 + b * (n - 1)
            return ans
        k = (n * b + a) // (a + b)
        m = n - k
        ans += a * k + b * m
        ans += calc(m, a, b)
        n = k
    return ans

