def is_valid(a, n):
    twos = [i for i in range(n) if a[i] == 2]
    if not twos:
        return False
    L = twos[0]
    R = twos[-1] + 1
    if any(a[i] != 2 for i in range(L, R)):
        return False
    if any(a[i] == 2 for i in range(n) if not (L <= i < R)):
        return False
    ones_ok = True
    for i in range(n):
        if a[i] == 1:
            if not ((i == L - 1 and L > 0) or (i == R and R < n)):
                ones_ok = False
                break
        elif a[i] not in (0, 2):
            ones_ok = False
            break
    expected_ones = []
    if L > 0:
        expected_ones.append(L - 1)
    if R < n:
        expected_ones.append(R)
    for i in expected_ones:
        if a[i] != 1:
            ones_ok = False
    return ones_ok

