    maxv = max(vs[i+1] - vs[i] for i in range(len(vs)-1))

    # For horizontal
    hs = sorted(hors)
    hprev = {}
    hnext = {}
    for i in range(len(hs)):
        if i > 0:
            hprev[hs[i]] = hs[i-1]
        if i < len(hs)-1:
            hnext[hs[i]] = hs[i+1]
    maxh = max(hs[i+1] - hs[i] for i in range(len(hs)-1))

    ans = [0] * n
