def query_argmax(L, R):
    if L > R:
        return L
    length = R - L + 1
    k = length.bit_length() - 1
    p1 = st[k][L]
    p2 = st[k][R - (1 << k) + 1]
    if a[p1] > a[p2] or (a[p1] == a[p2] and p1 > p2):
        return p1
    return p2

