def main():
    data = sys.stdin.read().split()
    n = int(data[0])
    x = int(data[1])
    a = [0] + [int(v) for v in data[2:2+n]]

    behind = [0] * (n + 1)
    for i in range(1, n + 1):
        if a[i] != 0:
            behind[a[i]] = i

    # Find all chain lengths and the chain of x
    visited = [False] * (n + 1)
    other_lengths = []
    my_len = 0
    my_pos = 0  # 1-based position from head

    for i in range(1, n + 1):
        if a[i] == 0 and not visited[i]:
            # start of a chain
            length = 0
            pos_x = 0
            cur = i
            while cur != 0:
                visited[cur] = True
                length += 1
                if cur == x:
                    pos_x = length
                cur = behind[cur]
            if pos_x > 0:
                my_len = length
                my_pos = pos_x
            else:
                other_lengths.append(length)

    # DP for possible subset sums of other_lengths
    maxs = n
    possible = [False] * (maxs + 1)
    possible[0] = True
    for L in other_lengths:
        for s in range(maxs - L, -1, -1):
            if possible[s]:
                possible[s + L] = True

    answers = []
    for s in range(maxs + 1):
        if possible[s]:
            pos = s + my_pos
            answers.append(pos)

    answers.sort()
    for p in answers:
        print(p)

