import math
from collections import defaultdict

MAX = 300000

def main():
    data = sys.stdin.read().split()
    n = int(data[0])
    A = list(map(int, data[1:]))

    spf = list(range(MAX + 1))
    for i in range(2, int(math.sqrt(MAX)) + 1):
        if spf[i] == i:
            for j in range(i * i, MAX + 1, i):
                if spf[j] == j:
                    spf[j] = i

    mu = [0] * (MAX + 1)
    mu[1] = 1
    for i in range(2, MAX + 1):
        p = spf[i]
        m = i // p
        if m % p == 0:
            mu[i] = 0
        else:
            mu[i] = -mu[m]

    freq = [0] * (MAX + 1)
    for a in A:
        freq[a] += 1

    f = [0] * (MAX + 1)
    for i in range(1, MAX + 1):
        for j in range(i, MAX + 1, i):
            f[i] += freq[j]

    occur = [False] * (MAX + 1)
    for a in A:
        x = a
        r = 1
        while x > 1:
            p = spf[x]
            r *= p
            while x % p == 0:
                x //= p
        occur[r] = True

    inf = 10**9
    ans = inf

    for s in range(1, MAX + 1):
        if not occur[s]:
            continue
        # factor s (square-free)
        primes = []
        x = s
        while x > 1:
            p = spf[x]
            primes.append(p)
            x //= p
        w = len(primes)
        full = (1 << w) - 1
        available = []
        # all t | s
        for mask_t in range(1 << w):
            t = 1
            kmask = 0
            for b in range(w):
                if mask_t & (1 << b):
                    t *= primes[b]
                else:
                    kmask |= (1 << b)
            k = s // t
            # sum mu[d] * f[t*d] for d|k
            sm = 0
            # d corresponding to submasks of kmask
            sub = kmask
            while True:
                d = 1
                for b in range(w):
                    if sub & (1 << b):
                        d *= primes[b]
                sm += mu[d] * f[t * d]
                if sub == 0:
                    break
                sub = (sub - 1) & kmask
            if sm > 0:
                # unkilled = mask_t, killed = full ^ mask_t
                killed = full ^ mask_t
                available.append(killed)

        # min set cover
        cov = [inf] * (1 << w)
        cov[0] = 0
        for msk in available:
            for st in range((1 << w) - 1, -1, -1):
                if cov[st] < inf:
                    nst = st | msk
                    if cov[nst] > cov[st] + 1:
                        cov[nst] = cov[st] + 1
        if cov[full] < inf:
            ans = min(ans, cov[full] + 1)

    if ans >= inf:
        print(-1)
    else:
        print(ans)

