import sys
sys.setrecursionlimit(1000000)

class TrieNode:
    def __init__(self):
        self.children = {}
        self.cnt = 0

class Trie:
    def __init__(self):
        self.root = TrieNode()

    def insert(self, word):
        node = self.root
        for c in word:
            if c not in node.children:
                node.children[c] = TrieNode()
            node = node.children[c]
            node.cnt += 1

    def min_unique_prefix(self, word):
        node = self.root
        for i, c in enumerate(word):
            if c not in node.children:
                return len(word)
            node = node.children[c]
            if node.cnt == 1:
                return i + 1
        return len(word)

def main():
    text = sys.stdin.read()
    n = len(text)
    clicks = 0
    seen = set()
    trie = Trie()
    i = 0
    while i < n:
        if 'a' <= text[i] <= 'z':
            j = i
            while j < n and 'a' <= text[j] <= 'z':
                j += 1
            word = text[i:j]
            length = j - i
            if word in seen:
                pref = trie.min_unique_prefix(word)
                clicks += min(length, pref + 1)
            else:
                clicks += length
                seen.add(word)
                trie.insert(word)
            i = j
        else:
            clicks += 1
            i += 1
    print(clicks)

