    main()

import sys

class TrieNode:
    __slots__ = ['children', 'count', 'word']
    def __init__(self):
        self.children = {}
        self.count = 0
        self.word = None

def insert(root, word):
    node = root
    node.count += 1
    for c in word:
        if c not in node.children:
            node.children[c] = TrieNode()
        node = node.children[c]
        node.count += 1
    node.word = word

def min_clicks(root, word):
    n = len(word)
    node = root
    best = n
    for i, c in enumerate(word):
        if c not in node.children:
            break
        node = node.children[c]
        if node.count == 1 and node.word == word and i + 1 < n:
            best = min(best, i + 2)
            break
    return best

def main():
    text = sys.stdin.read()
    root = TrieNode()
    seen = set()
    total = 0
    i = 0
    n = len(text)
    while i < n:
        if 'a' <= text[i] <= 'z':
            j = i
            while j < n and 'a' <= text[j] <= 'z':
                j += 1
            word = text[i:j]
            clicks = min_clicks(root, word)
            total += clicks
            if word not in seen:
                seen.add(word)
                insert(root, word)
            i = j
        else:
            total += 1
            i += 1
    print(total)

if __name__ == "__main__":
    main()

